// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.infrastructureimport timber.log.Timberimport android.content.Contextimport android.os.Buildimport android.os.PowerManagerimport java.io.File/** * NOUS — Android Thermal Probe (Module 6 v4 — Step 6.7). * * Real Android implementation of [ThermalProbe] — uses * [PowerManager.getThermalStatus] (API 29+) for a coarse thermal signal, * plus a `/sys/class/thermal/thermal_zoneN/temp` filesystem read for the * actual skin temperature in °C. * * ## Why this matters * * The [ThermalGovernor] needs the skin temperature to decide: *  - < 38 °C → full Omni-SLM (1080p RGB, 30 FPS) *  - 38-43 °C → reduced (720p grayscale, 15 FPS) *  - 43-48 °C → Omni-SLM disabled (camera-only + OCR) *  - ≥ 48 °C → vision fully suspended (cool-down period) * * ## How it works * *  1. Reads the CPU/skin thermal zone files under `/sys/class/thermal/`. *     Each `thermal_zoneN/temp` file contains the temperature in milli-°C *     (so divide by 1000). The probe scans for the first zone whose `type` *     file contains "skin", "cpu", or "soc" — these best approximate the *     case temperature that the user feels. *  2. Falls back to [PowerManager.getThermalStatus] (API 29+) if the sysfs *     read fails — this returns an enum (NONE/LIGHT/MODERATE/SEVERE/...) *     which we map to approximate °C values. *  3. Returns a sane default of 30 °C if both methods fail. * * ## Real Android APIs used * *  - [Context.getSystemService] → [PowerManager] *  - [PowerManager.getThermalStatus] (API 29+) *  - [File] reads on `/sys/class/thermal/thermal_zoneN/temp` + *    `/sys/class/thermal/thermal_zoneN/type` (Linux sysfs thermal zones) * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Thermal Governor</a> */class AndroidThermalProbe(    private val context: Context,) : ThermalProbe {    private val powerManager: PowerManager? =        context.getSystemService(Context.POWER_SERVICE) as? PowerManager    override suspend fun getSkinTemperatureCelsius(): Float {        // 1. Try reading the sysfs thermal zones (most accurate).        readSysfsSkinTemp()?.let { return it }        // 2. Fall back to PowerManager.getThermalStatus (coarse enum).        estimateFromPowerManager()?.let { return it }        // 3. Final fallback — sane default.        return 30f    }    /**     * Scan `/sys/class/thermal/` for the first skin/CPU/SOC thermal zone     * with a readable `temp` file. Returns the temperature in °C, or null     * if no zone could be read.     */    private fun readSysfsSkinTemp(): Float? {        return try {            val thermalDir = File("/sys/class/thermal")            if (!thermalDir.isDirectory) return null            val zones = thermalDir.listFiles { f -> f.name.startsWith("thermal_zone") }                ?: return null            // Prefer "skin" zones, then "cpu", then any.            val sortedZones = zones.sortedBy { zone ->                val type = try {                    File(zone, "type").readText().trim().lowercase()                } catch (t: Throwable) {                    ""                }                when {                    type.contains("skin") -> 0                    type.contains("cpu") -> 1                    type.contains("soc") -> 2                    else -> 3                }            }            for (zone in sortedZones) {                val tempFile = File(zone, "temp")                if (!tempFile.isFile) continue                try {                    val raw = tempFile.readText().trim().toFloatOrNull() ?: continue                    // Sysfs temps are in milli-°C — divide by 1000.                    val celsius = if (raw > 200f) raw / 1000f else raw                    if (celsius in -20f..120f) return celsius                } catch (t: Throwable) {                    // Skip to next zone.                }            }            null        } catch (t: Throwable) {            Timber.tag(TAG).w("Failed to read sysfs thermal zones.", t)            null        }    }    /**     * Map [PowerManager.getCurrentThermalStatus] → an approximate °C reading.     *     * The enum is intentionally coarse (only 7 buckets), so we map each     * bucket to the lower-bound temperature of its range, per the Android     * Thermal API spec.     */    private fun estimateFromPowerManager(): Float? {        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q) return null        val pm = powerManager ?: return null        return try {            val status = pm.getCurrentThermalStatus()            // Approximate lower-bound °C per PowerManager.THERMAL_STATUS_*.            when (status) {                PowerManager.THERMAL_STATUS_NONE -> 30f                PowerManager.THERMAL_STATUS_LIGHT -> 38f                PowerManager.THERMAL_STATUS_MODERATE -> 43f                PowerManager.THERMAL_STATUS_SEVERE -> 48f                PowerManager.THERMAL_STATUS_CRITICAL -> 53f                PowerManager.THERMAL_STATUS_EMERGENCY -> 58f                PowerManager.THERMAL_STATUS_SHUTDOWN -> 65f                else -> 30f            }        } catch (t: Throwable) {            Timber.tag(TAG).w("PowerManager.getCurrentThermalStatus failed.", t)            null        }    }    private companion object {        private const val TAG = "AndroidThermalProbe"    }}